package com.bank.stream.model;

// Represents a backlog of available records on a streaming source.
public class Backlog {
    private long available;

    public Backlog(long available) { this.available = available; }

    public long getAvailable() { return available; }

    // Take up to 'cap' records off the backlog and return how many were taken.
    public long take(long cap) {
        long taken = Math.min(cap, available);
        available -= taken;
        return taken;
    }
}
