package com.bank.stream.service;

import com.bank.stream.model.Backlog;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Simulates how different triggers drain a backlog.
public class TriggerRunner {

    private static final Logger log = Logger.getLogger(TriggerRunner.class.getName());

    // once(): one batch takes EVERYTHING, ignoring the rate limit (risky).
    public List<Long> runOnce(Backlog backlog) {
        long all = backlog.take(Long.MAX_VALUE);
        log.warning(() -> "once(): single batch ingested " + all + " records (rate limit ignored)");
        return List.of(all);
    }

    // availableNow(): multiple bounded batches respecting the per-trigger cap.
    public List<Long> runAvailableNow(Backlog backlog, long maxPerTrigger) {
        List<Long> batches = new ArrayList<>();
        while (backlog.getAvailable() > 0) {
            long taken = backlog.take(maxPerTrigger);
            batches.add(taken);
            log.info(() -> "availableNow(): batch ingested " + taken + " records (cap " + maxPerTrigger + ")");
        }
        log.info(() -> "availableNow(): drained in " + batches.size() + " batches, then stop");
        return batches;
    }
}
