package com.bank.stream;

import com.bank.stream.model.Backlog;
import com.bank.stream.service.TriggerRunner;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: compare once() vs availableNow() draining the same backlog.
public class TriggerModesDemo {

    private static final Logger log = Logger.getLogger(TriggerModesDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TriggerRunner runner = new TriggerRunner();

        log.info("=== once(): 25000 record backlog ===");
        runner.runOnce(new Backlog(25000));

        log.info("=== availableNow() with cap 10000: same 25000 backlog ===");
        runner.runAvailableNow(new Backlog(25000), 10000);

        log.info("Trigger modes demo complete.");
    }
}
